"use strict";(globalThis.webpackChunk=globalThis.webpackChunk||[]).push([[98865],{2036(e,r,n){n.r(r),n.d(r,{assets:()=>d,contentTitle:()=>o,default:()=>h,frontMatter:()=>a,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"YU13-limit-order-book/research","title":"Research: YU13-limit-order-book","description":"Why a crossing book replaces the price-triggered policy","source":"@site/../specs/YU13-limit-order-book/research.md","sourceDirName":"YU13-limit-order-book","slug":"/YU13-limit-order-book/research","permalink":"/traderX/specs/YU13-limit-order-book/research","draft":false,"unlisted":false,"editUrl":"https://github.com/YU-CS-Summer-2026-Distributed-TraderX/traderX/edit/YU15-eod-risk-extract/specs/../specs/YU13-limit-order-book/research.md","tags":[],"version":"current","frontMatter":{},"sidebar":"traderspecRootSpecsSidebar","previous":{"title":"\u2705 Tasks","permalink":"/traderX/specs/YU13-limit-order-book/tasks"},"next":{"title":"\ud83e\uddf1 Data Model","permalink":"/traderX/specs/YU13-limit-order-book/data-model"}}');var i=n(74848),s=n(28453);const a={},o="Research: YU13-limit-order-book",d={},c=[{value:"Why a crossing book replaces the price-triggered policy",id:"why-a-crossing-book-replaces-the-price-triggered-policy",level:2},{value:"Why array-indexed levels with intrusive lists",id:"why-array-indexed-levels-with-intrusive-lists",level:2},{value:"Why a 0.001 grid and a banded window",id:"why-a-0001-grid-and-a-banded-window",level:2},{value:"Why time priority needs no timestamps",id:"why-time-priority-needs-no-timestamps",level:2},{value:"Why the last price becomes an output",id:"why-the-last-price-becomes-an-output",level:2},{value:"Why egress acks carry a correlation class",id:"why-egress-acks-carry-a-correlation-class",level:2},{value:"What the throughput number means now",id:"what-the-throughput-number-means-now",level:2}];function l(e){const r={code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"research-yu13-limit-order-book",children:"Research: YU13-limit-order-book"})}),"\n",(0,i.jsx)(r.h2,{id:"why-a-crossing-book-replaces-the-price-triggered-policy",children:"Why a crossing book replaces the price-triggered policy"}),"\n",(0,i.jsxs)(r.p,{children:["The inherited matcher filled an order unilaterally whenever the security's last market price\nsatisfied its limit (",(0,i.jsx)(r.code,{children:"isInTheMoney"}),'), with a threshold policy half-filling large orders. That\npolicy has no counterparty: quantity appears from nowhere, the book only ever grows on one side,\nand depth means nothing. Every downstream consumer this system has grown \u2014 the risk engine\nmarking positions, the trade bridge feeding the DB and UI, the throughput bench counting booked\ntrades \u2014 becomes more meaningful when a fill is two orders agreeing on a price. Crossing is also\nthe only policy under which "book depth" and "best bid/ask" are real quantities the edge can\nserve.']}),"\n",(0,i.jsx)(r.h2,{id:"why-array-indexed-levels-with-intrusive-lists",children:"Why array-indexed levels with intrusive lists"}),"\n",(0,i.jsxs)(r.p,{children:["The book's hot operations are: find the best opposite level, take the FIFO head, reduce or\nunlink it, append a new resting order, and unlink a canceled order. With price levels as array\nslots on a fixed grid and orders as intrusive doubly-linked nodes (links live inside the pooled\n",(0,i.jsx)(r.code,{children:"RestingOrder"}),"), every one of these is O(1) with zero allocation \u2014 the same discipline the\nengine's dense ",(0,i.jsx)(r.code,{children:"ordersByRef"})," index and pooled entries already follow. Tree- or map-based books\nput a comparison structure and its allocation churn on the hottest path; the array trades a\nbounded, lazily-allocated band of memory for constant-time access and cache-friendly scans.\nBest-price maintenance uses per-side occupancy bitmaps: clearing the last order at the best\nlevel scans word-wise toward the next occupied level."]}),"\n",(0,i.jsx)(r.h2,{id:"why-a-0001-grid-and-a-banded-window",children:"Why a 0.001 grid and a banded window"}),"\n",(0,i.jsxs)(r.p,{children:["Prices travel the system as long ticks at the x1e6 ",(0,i.jsx)(r.code,{children:"Px"})," scale, rounded to 3dp HALF_UP at every\nedge. The book grid is therefore 0.001 \u2014 every price an edge can produce is exactly on-grid, and\ngrid rejection (",(0,i.jsx)(r.code,{children:"INVALID"}),") only ever fires for raw sub-0.001 ingress that no edge emits. With\nlevel price == resting limit price exactly, execution at the level price can never violate\neither side's limit."]}),"\n",(0,i.jsxs)(r.p,{children:["A full-range array at 0.001 granularity would be gigabytes; the band makes it megabytes. Each\nsecurity's window (default ",(0,i.jsx)(r.code,{children:"1<<17"})," ticks = $131.07) anchors mid-band on its first limit price \u2014\nthe warm-start seed data and the bench flow both trade each security in a narrow range around\none price, and a limit outside \xb1$65.5 of the anchor is exactly what an exchange price collar\nrejects. The band width and grid are config-identity values (like the output ring size): read\nonce at engine construction, identical on every member, and carried in the snapshot header so a\nrestored member adopts the geometry its state was built with."]}),"\n",(0,i.jsx)(r.h2,{id:"why-time-priority-needs-no-timestamps",children:"Why time priority needs no timestamps"}),"\n",(0,i.jsx)(r.p,{children:"Order references are assigned by the cluster service in committed-log order, so ascending\nreference IS arrival order IS time priority. This has two consequences the design leans on:\nFIFO within a level is maintained by plain tail-append at arrival; and the snapshot needs no\nbook-structure records at all beyond the band anchors \u2014 open rows serialized in ascending\nreference order re-append on restore into exactly the original per-level FIFO."}),"\n",(0,i.jsx)(r.h2,{id:"why-the-last-price-becomes-an-output",children:"Why the last price becomes an output"}),"\n",(0,i.jsxs)(r.p,{children:["With a crossing book the execution price is discovered by matching, not read from a reference\nfeed. The mark (",(0,i.jsx)(r.code,{children:"lastPxBySecurity"}),") is therefore written by trades and only seeded by market-data\nticks while no trade has printed \u2014 the seed lets an unpriced security bootstrap (trade-ticket\nbookings and market-order risk validation need a reference before the first cross). Risk\nprice-freshness state continues to consume every tick unchanged, so staleness checks and collar\ninputs are unaffected."]}),"\n",(0,i.jsx)(r.h2,{id:"why-egress-acks-carry-a-correlation-class",children:"Why egress acks carry a correlation class"}),"\n",(0,i.jsx)(r.p,{children:"The gateway's offer/ack accounting relies on acks being FIFO per session. The inherited design\ndocumented its own limit: async updates for resting orders would interleave and skew the count.\nA crossing book makes counterparty updates the common case \u2014 every cross emits an update for a\nresting order that belongs to no in-flight offer. One spare byte in the fixed 24-byte ack now\nclasses each order-lifecycle ack as direct or resting-update; correlation and batch accounting\nconsume only direct acks. Ack length and all existing fields are unchanged, so a client ignoring\nthe byte sees the previous wire shape."}),"\n",(0,i.jsx)(r.h2,{id:"what-the-throughput-number-means-now",children:"What the throughput number means now"}),"\n",(0,i.jsx)(r.p,{children:"A booked-fill event counts each SIDE of a cross: one match step books two trades (two trade\nsequence numbers, one per account). The bench's booked/s numerator therefore counts filled-order\nevents exactly as before, but the flow generating them must be genuinely two-sided and\nmarketable \u2014 numbers measured against the auto-fill engine are not comparable and are not\ncarried forward (NFR-LOB03)."})]})}function h(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},28453(e,r,n){n.d(r,{R:()=>a,x:()=>o});var t=n(96540);const i={},s=t.createContext(i);function a(e){const r=t.useContext(s);return t.useMemo(function(){return"function"==typeof e?e(r):{...r,...e}},[r,e])}function o(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),t.createElement(s.Provider,{value:r},e.children)}}}]);